\\ L2_verify_v3.gp -- PARI/GP 2.15+ : Stage38 L2-05 / L2-06 の全検査（再現用）
\\ 使い方: gp -q -s 1G  の中で  read("L2_verify_v3.gp")
\\ 乱数は setrand で固定。各検査の最後に件数と失敗数を表示する。
ehomo(e1,e2,e3) = ellinit([0,-(e1+e2+e3),0,e1*e2+e1*e3+e2*e3,-e1*e2*e3]);
Erho(a,b) = my(k=4*a*b*(a^2-b^2)); ehomo(k,-k,-(a^2+b^2)^2);
Etau(a,b) = my(n=a^2-b^2,m=a*b); ehomo(8*n^2*m^2,-8*n^2*m^2,-(n^4+16*m^4));
Esig(a,b) = my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2); ellinit([0,P^2+Q^2,0,P^2*Q^2,0]);
oddp(x) = my(y=abs(x)); y/2^valuation(y,2);
om(x) = omega(oddp(x));
n1mod8(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%8==1);
c1mod4(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%4==1);
c3mod4(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%4==3);
eps(a,b) = my(m=a*b); if(m%4==2, 1, if(m%2==1 && (m%8==3 || m%8==5), 1, -1));
thm(a,b) = my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2, N1=om(a*b*(a^2-b^2))+n1mod8(P*Q)); [-eps(a,b)*(-1)^N1, (-1)^(N1+om(a^2+b^2))];
wsig(a,b) = my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2); (-1)^(om(P*Q) + c1mod4(a*b*(a^2-b^2)));
\\ C3_p の3つの商（4次式の Jacobian は ellfromeqn）
Qsig(a,b) = my(p=a/b, c=(a+b)/(a-b)); ellinit(ellfromeqn(y^2-(x+p^2)*(x+p^-2)*(x+c^2)*(x+c^-2)));
Qone(a,b) = my(p=a/b, h=p-1/p); ellinit(ellfromeqn(y^2-(x^2+h^2)*(x^2+16/h^2)));
Qmone(a,b) = my(p=a/b, h=p-1/p, r=p+1/p); ellinit(ellfromeqn(y^2-(x^2+r^2)*(x^2+4*r^2/h^2)));
isom(E,F) = ellisisom(E,F) != 0;
Fq(u,a,b) = my(p=a/b, c=(a+b)/(a-b)); (u+p^2)*(u+p^-2)*(u+c^2)*(u+c^-2);

\\ S1: 商の同定 (t->1/t ~ E_tau, t->-1/t ~ E_rho, t->-t ~ E_sigma)、1<=b<a<20
{my(c=0,bad=0); for(a=2,19, for(b=1,a-1, if(gcd(a,b)==1, c++;
   if(!isom(Qone(a,b),Etau(a,b)) || !isom(Qmone(a,b),Erho(a,b)) || !isom(Qsig(a,b),Esig(a,b)) || isom(Esig(a,b),Erho(a,b)) || isom(Esig(a,b),Etau(a,b)), bad++; print("S1 FAIL ",a,"/",b)))));
 print("S1 quotients identified a<20: tested ",c," failures ",bad);}

\\ S2: E_sigma = E_rho の Q(i) による twist、1<=b<a<50
{my(c=0,bad=0); for(a=2,49, for(b=1,a-1, if(gcd(a,b)==1, c++;
   if(!isom(ellinit(elltwist(Erho(a,b),-4)),Esig(a,b)), bad++; print("S2 FAIL ",a,"/",b)))));
 print("S2 E_sigma = twist(E_rho,-4) a<50: tested ",c," failures ",bad);}

\\ S3: w(E_sigma) の式と w2(E_sigma)=-1：a<80 の全組、負を含む |a|,|b|<=40 の全組、乱択1500（種 3）
oks(a,b) = my(E=Esig(a,b)); ellrootno(E)==wsig(a,b) && ellrootno(E,2)==-1;
{my(c=0,bad=0,a,b);
 for(a=2,79, for(b=1,a-1, if(gcd(a,b)==1, c++; if(!oks(a,b), bad++; print("S3 FAIL ",a,"/",b)))));
 for(a=-40,40, for(b=-40,40, if(a*b!=0 && abs(a)!=abs(b) && gcd(a,b)==1, c++; if(!oks(a,b), bad++; print("S3 FAIL ",a,"/",b)))));
 setrand(3); for(i=1,1500, a=random(10^9)+2; b=random(10^6)+1; if(gcd(a,b)!=1 || a==b, next); c++; if(!oks(a,b), bad++; print("S3 FAIL ",a,"/",b)));
 print("S3 w(E_sigma) formula and w2=-1: tested ",c," failures ",bad);}

\\ S4: 積の式 w_rho*w_sigma = -eps*(-1)^#{l | ab(a^2-b^2)PQ, l=3 mod 4}、a<120
{my(c=0,bad=0,P,Q); for(a=2,119, for(b=1,a-1, if(gcd(a,b)==1, c++; P=a^2+2*a*b-b^2; Q=a^2-2*a*b-b^2;
   if(thm(a,b)[1]*wsig(a,b) != -eps(a,b)*(-1)^c3mod4(a*b*(a^2-b^2)*P*Q), bad++; print("S4 FAIL ",a,"/",b)))));
 print("S4 product formula a<120: tested ",c," failures ",bad);}

\\ S5: 2進：y^2=x(x+t)(x-1), v2(t) in [4,12] で w2=-1（種 5）
{my(c=0,bad=0,k,t); setrand(5); for(i=1,4000, k=4+random(9); t=(2*random(10^5)+1)*2^k/(2*random(10^5)+1)*(-1)^random(2);
   if(t==1, next); c++; if(ellrootno(ellinit([0,t-1,0,-t,0]),2)!=-1, bad++; print("S5 FAIL t=",t)));
 print("S5 w2 of twisted E(t) (seed 5): tested ",c," failures ",bad);}

\\ S6: (w_rho, w_sigma, w_tau) の分布、b<a<N
dist(N) = {my(v=vector(8),c=0,w,k); for(a=2,N-1, for(b=1,a-1, if(gcd(a,b)==1, c++; w=[thm(a,b)[1],wsig(a,b),thm(a,b)[2]];
   k=1+(w[1]<0)*4+(w[2]<0)*2+(w[3]<0); v[k]++))); print("S6 N=",N," pairs=",c," counts (+++,++-,+-+,+--,-++,-+-,--+,---)=",v);}
dist(100); dist(200);

\\ S7: 3つとも -1 の例（a<60 の件数）と、p=23, 11/6, 10 の rank
{my(c=0); for(a=2,59, for(b=1,a-1, if(gcd(a,b)==1 && thm(a,b)==[-1,-1] && wsig(a,b)==-1, c++))); print("S7 triple -1 with a<60: ",c);}
{foreach([[23,1],[11,6],[10,1]], q, my(a=q[1],b=q[2]);
   print("S7 p=",a,"/",b," rho: w=",ellrootno(Erho(a,b))," rank ",ellrank(Erho(a,b))[1..2],
         "  sigma: w=",ellrootno(Esig(a,b))," rank ",ellrank(Esig(a,b))[1..2],
         "  tau: w=",ellrootno(Etau(a,b))," rank ",ellrank(Etau(a,b))[1..2]));}

\\ S8: L2-06 の点 R0 = (PQ b^2/a^2, b(a^2-b^2)^2 PQ/a^3)
\\ (i) 記号計算：a,b を変数として y0^2 = x0(x0+P^2)(x0+Q^2) が恒等式
{my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2, x0=P*Q*b^2/a^2, y0=b*(a^2-b^2)^2*P*Q/a^3);
 print("S8(i) symbolic identity y0^2 - f(x0) = ", simplify(y0^2 - x0*(x0+P^2)*(x0+Q^2)));}
\\ (ii) 数値：a<30 で R0 が曲線上、|a|>=2 で x0 が非整数、ellrank の分布
{my(c=0,bad=0,P,Q,E,r,tab=Map(),key);
 for(a=2,29, for(b=1,a-1, if(gcd(a,b)==1, c++; P=a^2+2*a*b-b^2; Q=a^2-2*a*b-b^2; E=Esig(a,b);
   if(!ellisoncurve(E,[P*Q*b^2/a^2, b*(a^2-b^2)^2*P*Q/a^3]) || denominator(P*Q*b^2/a^2)==1, bad++; print("S8 FAIL ",a,"/",b));
   r=ellrank(E); key=[ellrootno(E),r[1],r[2]]; mapput(tab,key,if(mapisdefined(tab,key),mapget(tab,key),0)+1))));
 print("S8(ii) R0 on curve and non-integral a<30: tested ",c," failures ",bad);
 print("S8(ii) [w_sigma, rank_lo, rank_hi] -> count: ", Mat(tab));}
\\ (iii) D_sigma の u=0,1,-1 で F(u) が平方、E_sigma の torsion がちょうど Z/2xZ/4、a<200
{my(c=0,bad=0,tb=0); for(a=2,199, for(b=1,a-1, if(gcd(a,b)==1, c++;
   if(!issquare(Fq(0,a,b)) || !issquare(Fq(1,a,b)) || !issquare(Fq(-1,a,b)), bad++);
   if(elltors(Esig(a,b))[2]!=[4,2], tb++))));
 print("S8(iii) F(0),F(1),F(-1) squares a<200: tested ",c," failures ",bad,"   torsion != Z/2xZ/4: ",tb);}

\\ 期待される出力（PARI/GP 2.17.2、約16秒）:
\\ S1 quotients identified a<20: tested 119 failures 0
\\ S2 E_sigma = twist(E_rho,-4) a<50: tested 753 failures 0
\\ S3 w(E_sigma) formula and w2=-1: tested 6781 failures 0
\\ S4 product formula a<120: tested 4353 failures 0
\\ S5 w2 of twisted E(t) (seed 5): tested 4000 failures 0
